import{_ as e,o as a,c as t,a5 as o}from"./chunks/framework.Bt0SrEfo.js";const p=JSON.parse('{"title":"网络推荐深入阅读","description":"","frontmatter":{},"headers":[],"relativePath":"网络/21-further-reading.md","filePath":"网络/21-further-reading.md","lastUpdated":1790091846000}'),l={name:"网络/21-further-reading.md"};function n(s,r,i,h,g,c){return a(),t("div",null,[...r[0]||(r[0]=[o(`<h1 id="网络推荐深入阅读" tabindex="-1">网络推荐深入阅读 <a class="header-anchor" href="#网络推荐深入阅读" aria-label="Permalink to &quot;网络推荐深入阅读&quot;">​</a></h1><h2 id="经典书籍" tabindex="-1">经典书籍 <a class="header-anchor" href="#经典书籍" aria-label="Permalink to &quot;经典书籍&quot;">​</a></h2><ul><li><p><strong>《HTTP 权威指南》(HTTP: The Definitive Guide)</strong> —— David Gourley / Brian Totty。HTTP 协议的&quot;圣经&quot;,从协议演进到详细字段,从缓存到代理。<strong>强烈建议至少读前 12 章</strong>。</p></li><li><p><strong>《计算机网络:自顶向下方法》(Computer Networking: A Top-Down Approach)</strong> —— James Kurose / Keith Ross。从应用层开始讲,逐步深入。教材级质量,适合系统化学习。</p></li><li><p><strong>《TCP/IP 详解 卷一:协议》(TCP/IP Illustrated, Volume 1: The Protocols)</strong> —— W. Richard Stevens。TCP/IP 协议栈深度讲解,<strong>网络工程师必读</strong>。</p></li><li><p><strong>《Web 性能权威指南》(High Performance Browser Networking)</strong> —— Ilya Grigorik。Google 性能团队出品,网络、HTTPS、HTTP/2、缓存都涵盖。</p></li><li><p><strong>《HTTP/2 详解》(http2-explained)</strong> —— Daniel Stenberg(cURL 作者)。免费电子书,中文版质量也很好。HTTP/2 入门首选。</p></li><li><p><strong>《HTTPS 权威指南》(Bulletproof SSL and TLS)</strong> —— Ivan Ristic(SSL Labs 创始人)。HTTPS 配置、证书、攻击防御全面覆盖。</p></li></ul><h2 id="google-官方资源" tabindex="-1">Google 官方资源 <a class="header-anchor" href="#google-官方资源" aria-label="Permalink to &quot;Google 官方资源&quot;">​</a></h2><h3 id="web-dev" tabindex="-1">web.dev <a class="header-anchor" href="#web-dev" aria-label="Permalink to &quot;web.dev&quot;">​</a></h3><ul><li><strong><a href="https://web.dev/http/" target="_blank" rel="noreferrer">web.dev HTTP</a></strong> —— HTTP 性能优化</li><li><strong><a href="https://web.dev/http-cache/" target="_blank" rel="noreferrer">web.dev Caching</a></strong> —— 缓存策略</li><li><strong><a href="https://web.dev/http2/" target="_blank" rel="noreferrer">web.dev HTTP/2</a></strong> —— HTTP/2 详解</li><li><strong><a href="https://web.dev/http3-explained/" target="_blank" rel="noreferrer">web.dev HTTP/3</a></strong> —— HTTP/3 详解</li><li><strong><a href="https://web.dev/cross-origin-resource-sharing/" target="_blank" rel="noreferrer">web.dev CORS</a></strong> —— CORS 配置</li></ul><h3 id="chrome-团队博客" tabindex="-1">Chrome 团队博客 <a class="header-anchor" href="#chrome-团队博客" aria-label="Permalink to &quot;Chrome 团队博客&quot;">​</a></h3><ul><li><strong><a href="https://httparchive.org/" target="_blank" rel="noreferrer">HTTP Archive</a></strong> —— Web 性能数据统计</li><li><strong><a href="https://www.chromestatus.com/features" target="_blank" rel="noreferrer">Chrome Status</a></strong> —— 新特性追踪</li></ul><h2 id="规范与标准-必读" tabindex="-1">规范与标准(必读) <a class="header-anchor" href="#规范与标准-必读" aria-label="Permalink to &quot;规范与标准(必读)&quot;">​</a></h2><ul><li><strong><a href="https://datatracker.ietf.org/doc/html/rfc9110" target="_blank" rel="noreferrer">RFC 9110 (HTTP Semantics)</a></strong> —— HTTP 语义</li><li><strong><a href="https://datatracker.ietf.org/doc/html/rfc9112" target="_blank" rel="noreferrer">RFC 9112 (HTTP/1.1)</a></strong> —— HTTP/1.1</li><li><strong><a href="https://datatracker.ietf.org/doc/html/rfc9113" target="_blank" rel="noreferrer">RFC 9113 (HTTP/2)</a></strong> —— HTTP/2</li><li><strong><a href="https://datatracker.ietf.org/doc/html/rfc9114" target="_blank" rel="noreferrer">RFC 9114 (HTTP/3)</a></strong> —— HTTP/3</li><li><strong><a href="https://datatracker.ietf.org/doc/html/rfc9000" target="_blank" rel="noreferrer">RFC 9000 (QUIC)</a></strong> —— QUIC 协议</li><li><strong><a href="https://datatracker.ietf.org/doc/html/rfc6265" target="_blank" rel="noreferrer">RFC 6265 (Cookies)</a></strong> —— HTTP Cookie</li><li><strong><a href="https://datatracker.ietf.org/doc/html/rfc6455" target="_blank" rel="noreferrer">RFC 6455 (WebSocket)</a></strong> —— WebSocket</li><li><strong><a href="https://datatracker.ietf.org/doc/html/rfc9293" target="_blank" rel="noreferrer">RFC 793 / 9293 (TCP)</a></strong> —— TCP</li><li><strong><a href="https://datatracker.ietf.org/doc/html/rfc768" target="_blank" rel="noreferrer">RFC 768 (UDP)</a></strong> —— UDP</li></ul><h2 id="在线文档" tabindex="-1">在线文档 <a class="header-anchor" href="#在线文档" aria-label="Permalink to &quot;在线文档&quot;">​</a></h2><ul><li><strong><a href="https://developer.mozilla.org/zh-CN/docs/Web/HTTP" target="_blank" rel="noreferrer">MDN HTTP</a></strong> —— HTTP 全家桶</li><li><strong><a href="https://developer.mozilla.org/zh-CN/docs/Web/API/WebSocket" target="_blank" rel="noreferrer">MDN WebSocket</a></strong> —— WebSocket</li><li><strong><a href="https://developer.mozilla.org/zh-CN/docs/Web/API/Fetch_API" target="_blank" rel="noreferrer">MDN Fetch</a></strong> —— Fetch API</li></ul><h2 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h2><h3 id="调试工具" tabindex="-1">调试工具 <a class="header-anchor" href="#调试工具" aria-label="Permalink to &quot;调试工具&quot;">​</a></h3><ul><li><strong><a href="https://developer.chrome.com/docs/devtools/network/" target="_blank" rel="noreferrer">Chrome DevTools Network</a></strong> —— 必备</li><li><strong><a href="https://www.charlesproxy.com/" target="_blank" rel="noreferrer">Charles Proxy</a></strong> —— HTTPS 抓包</li><li><strong><a href="https://www.wireshark.org/" target="_blank" rel="noreferrer">Wireshark</a></strong> —— 协议级分析</li><li><strong><a href="https://www.postman.com/" target="_blank" rel="noreferrer">Postman</a> / <a href="https://insomnia.rest/" target="_blank" rel="noreferrer">Insomnia</a></strong> —— API 测试</li></ul><h3 id="测试-评分" tabindex="-1">测试 / 评分 <a class="header-anchor" href="#测试-评分" aria-label="Permalink to &quot;测试 / 评分&quot;">​</a></h3><ul><li><strong><a href="https://www.ssllabs.com/ssltest/" target="_blank" rel="noreferrer">SSL Labs Server Test</a></strong> —— HTTPS 配置评分</li><li><strong><a href="https://securityheaders.com/" target="_blank" rel="noreferrer">Security Headers</a></strong> —— HTTP Headers 安全评分</li><li><strong><a href="https://www.webpagetest.org/" target="_blank" rel="noreferrer">WebPageTest</a></strong> —— 全球多地点性能测试</li><li><strong><a href="https://http2.pro/" target="_blank" rel="noreferrer">HTTP/2 Test</a></strong> —— HTTP/2 支持测试</li></ul><h3 id="协议追踪" tabindex="-1">协议追踪 <a class="header-anchor" href="#协议追踪" aria-label="Permalink to &quot;协议追踪&quot;">​</a></h3><ul><li><strong><a href="https://caniuse.com/" target="_blank" rel="noreferrer">Can I Use</a></strong> —— 浏览器特性支持</li><li><strong><a href="https://www.chromestatus.com/features" target="_blank" rel="noreferrer">Chrome Platform Status</a></strong> —— Chrome 新特性</li></ul><h2 id="视频-课程" tabindex="-1">视频 / 课程 <a class="header-anchor" href="#视频-课程" aria-label="Permalink to &quot;视频 / 课程&quot;">​</a></h2><ul><li><strong><a href="https://www.youtube.com/@GoogleChromeDevelopers" target="_blank" rel="noreferrer">Google Chrome Developers YouTube</a></strong> —— 大量 HTTP/HTTPS 视频</li><li><strong><a href="https://www.udacity.com/course/computer-networking--ud436" target="_blank" rel="noreferrer">Computer Networking - Georgia Tech</a></strong> —— 免费 Udacity 课程</li><li><strong><a href="https://www.coursera.org/" target="_blank" rel="noreferrer">HTTP &amp; Web Servers - Coursera</a></strong> —— 多门相关课程</li></ul><h2 id="实战项目" tabindex="-1">实战项目 <a class="header-anchor" href="#实战项目" aria-label="Permalink to &quot;实战项目&quot;">​</a></h2><ul><li><strong><a href="https://websocket.org/echo.html" target="_blank" rel="noreferrer">Echo WebSocket Service</a></strong> —— 测试 WebSocket</li><li><strong><a href="https://httpbin.org/" target="_blank" rel="noreferrer">HTTPBin</a></strong> —— 测试 HTTP 各种场景</li><li><strong><a href="https://github.com/reorx/httpstat" target="_blank" rel="noreferrer">httpstat</a></strong> —— 看 HTTP 各阶段耗时</li></ul><h2 id="推荐路径" tabindex="-1">推荐路径 <a class="header-anchor" href="#推荐路径" aria-label="Permalink to &quot;推荐路径&quot;">​</a></h2><h3 id="入门-1-2-周" tabindex="-1">入门(1~2 周) <a class="header-anchor" href="#入门-1-2-周" aria-label="Permalink to &quot;入门(1~2 周)&quot;">​</a></h3><ol><li>《HTTP 权威指南》第 1~6 章(协议基础)</li><li>web.dev HTTP 专题</li><li>MDN HTTP 文档速览</li></ol><h3 id="进阶-1-2-月" tabindex="-1">进阶(1~2 月) <a class="header-anchor" href="#进阶-1-2-月" aria-label="Permalink to &quot;进阶(1~2 月)&quot;">​</a></h3><ol><li>《计算机网络:自顶向下方法》第 1~3 章</li><li>《Web 性能权威指南》</li><li>《HTTP/2 详解》(免费电子书)</li></ol><h3 id="高级-2-3-月" tabindex="-1">高级(2~3 月+) <a class="header-anchor" href="#高级-2-3-月" aria-label="Permalink to &quot;高级(2~3 月+)&quot;">​</a></h3><ol><li>《TCP/IP 详解》</li><li>RFC 9110(选择性读)</li><li>QUIC / HTTP/3 源码学习</li></ol><h2 id="关键问题清单-面试常考" tabindex="-1">关键问题清单(面试常考) <a class="header-anchor" href="#关键问题清单-面试常考" aria-label="Permalink to &quot;关键问题清单(面试常考)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✅ HTTP/1.1 vs HTTP/2 vs HTTP/3 的核心区别</span></span>
<span class="line"><span>✅ HTTPS 握手过程(TLS 1.2 vs 1.3)</span></span>
<span class="line"><span>✅ 强缓存 vs 协商缓存</span></span>
<span class="line"><span>✅ CORS 简单请求 vs 预检</span></span>
<span class="line"><span>✅ SameSite 三个值</span></span>
<span class="line"><span>✅ TCP 三次握手 / 四次挥手</span></span>
<span class="line"><span>✅ WebSocket vs HTTP 长连接</span></span>
<span class="line"><span>✅ 输入 URL 到页面渲染的完整流程</span></span>
<span class="line"><span>✅ CDN / DNS 优化</span></span></code></pre></div><p>读完推荐资料,这些问题都能答上来。</p><h2 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h2><ul><li><strong>RFC 是终极权威</strong>——但篇幅大,建议先读导论/教程,再回头查 RFC</li><li><strong>生产配置</strong>参考 Nginx / Cloudflare 文档,不要照搬博客(博客版本老)</li><li><strong>安全</strong>最关键的:HTTPS 配置 + Cookie 安全 + CSP + 输入验证,任何一环缺失都可能出问题</li></ul>`,35)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
